-- Purple Boutique billing backend.
-- This migration is for a fresh Purple Boutique Supabase project only.
-- No source-business data, identifiers, credentials, or production records belong here.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE public.profiles (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  customer_code text UNIQUE,
  name text NOT NULL DEFAULT '',
  full_name text NOT NULL DEFAULT '',
  mobile text NOT NULL DEFAULT '',
  mobile_country_code text,
  mobile_number text,
  email text,
  role text NOT NULL DEFAULT 'customer' CHECK (role IN ('admin','staff','customer')),
  avatar_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE SEQUENCE public.customer_code_seq START 1;

CREATE TABLE public.categories (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_en text NOT NULL UNIQUE,
  name_ta text NOT NULL DEFAULT '',
  is_active boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.products (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL, name_ta text NOT NULL DEFAULT '', tamil_name text NOT NULL DEFAULT '',
  category text NOT NULL DEFAULT '', category_id bigint REFERENCES public.categories(id) ON DELETE SET NULL,
  remedy text[] NOT NULL DEFAULT '{}', price numeric(12,2) NOT NULL DEFAULT 0,
  offer_price numeric(12,2), purchase_price numeric(12,2) NOT NULL DEFAULT 0, mrp numeric(12,2) NOT NULL DEFAULT 0,
  gst_percent numeric(5,2) NOT NULL DEFAULT 0, unit_type text NOT NULL DEFAULT 'unit', unit_label text NOT NULL DEFAULT 'piece', unit text NOT NULL DEFAULT 'piece',
  base_quantity numeric(12,3) NOT NULL DEFAULT 1, stock_quantity numeric(12,3) NOT NULL DEFAULT 0, opening_stock numeric(12,3) NOT NULL DEFAULT 0,
  stock integer NOT NULL DEFAULT 0, stock_unit text NOT NULL DEFAULT 'piece', low_stock_alert numeric(12,3) NOT NULL DEFAULT 5,
  allow_decimal_quantity boolean NOT NULL DEFAULT false, predefined_options jsonb NOT NULL DEFAULT '[]', description text NOT NULL DEFAULT '', description_ta text NOT NULL DEFAULT '',
  benefits text NOT NULL DEFAULT '', benefits_ta text NOT NULL DEFAULT '', image text, image_url text, sku text, barcode text, brand text, supplier text, size text, color text,
  rating numeric(3,1) NOT NULL DEFAULT 5, has_variants boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0,
  lens_type_id bigint, pricing_type text NOT NULL DEFAULT 'standard', product_type text NOT NULL DEFAULT 'general', brand_type text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX products_category_idx ON public.products(category_id, is_active, sort_order);

CREATE TABLE public.product_variants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id bigint NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  variant_name text NOT NULL, size_label text, weight_value numeric(12,3), weight_unit text, sku text, barcode text,
  purchase_price numeric(12,2), mrp numeric(12,2), price numeric(12,2) NOT NULL DEFAULT 0, stock numeric(12,3) NOT NULL DEFAULT 0,
  is_default boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, image_url text, group_name text,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id, variant_name)
);

CREATE TABLE public.product_prices (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint REFERENCES public.products(id) ON DELETE CASCADE,
  product_name text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL DEFAULT 0, offer_price numeric(12,2), valid_from date NOT NULL DEFAULT current_date, valid_to date
);
CREATE TABLE public.lens_types (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0
);
CREATE TABLE public.lens_addons (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL DEFAULT 0, pricing_type text NOT NULL DEFAULT 'fixed', is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0
);

CREATE TABLE public.coupons (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code text NOT NULL, discount_type text NOT NULL DEFAULT 'percentage' CHECK (discount_type IN ('percentage','fixed')),
  discount_value numeric(12,2) NOT NULL CHECK (discount_value > 0), percentage numeric(5,2) NOT NULL DEFAULT 0 CHECK (percentage >= 0 AND percentage <= 100),
  maximum_discount numeric(12,2), min_order_value numeric(12,2) NOT NULL DEFAULT 0,
  valid_from timestamptz, valid_until timestamptz, expiry_date timestamptz,
  usage_limit integer CHECK (usage_limit IS NULL OR usage_limit > 0), usage_count integer NOT NULL DEFAULT 0 CHECK (usage_count >= 0),
  applicable_product_ids bigint[] NOT NULL DEFAULT '{}', applicable_categories text[] NOT NULL DEFAULT '{}',
  is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX coupons_code_unique ON public.coupons (upper(btrim(code)));

CREATE TABLE public.orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_no text NOT NULL UNIQUE, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  customer_name text NOT NULL DEFAULT 'Customer', phone text NOT NULL DEFAULT '', phone_country_code text, phone_number text, address text NOT NULL DEFAULT '', items jsonb NOT NULL DEFAULT '[]',
  subtotal numeric(12,2) NOT NULL DEFAULT 0, shipping numeric(12,2) NOT NULL DEFAULT 0, delivery_charge numeric(12,2) NOT NULL DEFAULT 0,
  discount_amount numeric(12,2) NOT NULL DEFAULT 0, coupon_id bigint REFERENCES public.coupons(id) ON DELETE SET NULL, coupon_code text, coupon_percentage numeric(5,2) NOT NULL DEFAULT 0, coupon_discount_amount numeric(12,2) NOT NULL DEFAULT 0,
  manual_discount_amount numeric(12,2) NOT NULL DEFAULT 0, manual_discount_type text NOT NULL DEFAULT 'flat', manual_discount_value numeric(12,2) NOT NULL DEFAULT 0,
  total_gst numeric(12,2) NOT NULL DEFAULT 0, gst_amount numeric(12,2) NOT NULL DEFAULT 0, gst_enabled boolean NOT NULL DEFAULT false, total numeric(12,2) NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'pending', order_mode text NOT NULL DEFAULT 'offline', order_type text NOT NULL DEFAULT 'pos_sale', payment_method text NOT NULL DEFAULT 'cash', payment_mode text NOT NULL DEFAULT 'cash', split_details jsonb NOT NULL DEFAULT '{}',
  invoice_pdf_url text, remarks text NOT NULL DEFAULT '', reference_number text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.order_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, product_id bigint REFERENCES public.products(id) ON DELETE SET NULL, variant_id uuid REFERENCES public.product_variants(id) ON DELETE SET NULL,
  product_name text NOT NULL DEFAULT 'Product', name text NOT NULL DEFAULT 'Product', product_tamil_name text, tamil_name text, category text NOT NULL DEFAULT '', quantity numeric(12,3) NOT NULL DEFAULT 0, unit text NOT NULL DEFAULT 'piece', unit_type text NOT NULL DEFAULT 'unit', base_quantity numeric(12,3) NOT NULL DEFAULT 1,
  base_price numeric(12,2) NOT NULL DEFAULT 0, unit_price numeric(12,2) NOT NULL DEFAULT 0, line_total numeric(12,2) NOT NULL DEFAULT 0, image_url text, is_manual boolean NOT NULL DEFAULT false, source text NOT NULL DEFAULT 'catalogue', discount numeric(12,2) NOT NULL DEFAULT 0, gst_amount numeric(12,2) NOT NULL DEFAULT 0, gst_rate numeric(5,2) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.advance_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deposit_id text NOT NULL UNIQUE, customer_name text NOT NULL, phone text NOT NULL, phone_country_code text, phone_number text, address text NOT NULL DEFAULT '', product_name text NOT NULL, products jsonb NOT NULL DEFAULT '[]', category text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '',
  total_amount numeric(12,2) NOT NULL CHECK (total_amount > 0), deposit_amount numeric(12,2) NOT NULL CHECK (deposit_amount > 0), remaining_balance numeric(12,2) GENERATED ALWAYS AS (total_amount - deposit_amount) STORED,
  expected_delivery_date date NOT NULL, status text NOT NULL DEFAULT 'pending_deposit' CHECK (status IN ('pending_deposit','ready_for_delivery','waiting_final_payment','completed','cancelled')), remarks text NOT NULL DEFAULT '', reference_number text NOT NULL DEFAULT '', created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_by_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, completed_order_id uuid UNIQUE REFERENCES public.orders(id) ON DELETE SET NULL, invoice_number text UNIQUE, final_payment_method text, CHECK (deposit_amount < total_amount)
);
CREATE TABLE public.advance_order_timeline (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, advance_order_id uuid NOT NULL REFERENCES public.advance_orders(id) ON DELETE CASCADE, event_type text NOT NULL, label text NOT NULL, remarks text NOT NULL DEFAULT '', created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.advance_order_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), advance_order_id uuid NOT NULL REFERENCES public.advance_orders(id) ON DELETE CASCADE, payment_type text NOT NULL CHECK (payment_type IN ('deposit','remaining')), amount numeric(12,2) NOT NULL CHECK (amount >= 0), payment_method text NOT NULL CHECK (payment_method IN ('cash','upi','card')), remarks text NOT NULL DEFAULT '', received_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(advance_order_id, payment_type));
CREATE SEQUENCE public.invoice_number_seq START 1;
CREATE SEQUENCE public.deposit_number_seq START 1;
CREATE TABLE public.store_settings (id smallint PRIMARY KEY DEFAULT 1 CHECK (id = 1), name text NOT NULL DEFAULT 'Specson', owner_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', gst_enabled boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.store_settings(id, name) VALUES (1, 'Specson');

CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role IN ('admin','staff')); $$;
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','categories','products','product_variants','coupons','orders','advance_orders','store_settings'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()', t || '_touch', t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,customer_code,name,full_name,mobile,email,role) VALUES(NEW.id,'PB-'||lpad(nextval('public.customer_code_seq')::text,6,'0'),coalesce(nullif(NEW.raw_user_meta_data->>'name',''),split_part(coalesce(NEW.email,''),'@',1),'Customer'),coalesce(nullif(NEW.raw_user_meta_data->>'name',''),''),coalesce(NEW.raw_user_meta_data->>'mobile',''),NEW.email,CASE WHEN NEW.raw_user_meta_data->>'role'='admin' THEN 'admin' ELSE 'customer' END) ON CONFLICT(id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

CREATE OR REPLACE FUNCTION public.validate_coupon(p_code text, p_subtotal numeric, p_product_ids bigint[] DEFAULT '{}', p_category_names text[] DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE c public.coupons; d numeric; BEGIN SELECT * INTO c FROM public.coupons WHERE upper(btrim(code))=upper(btrim(p_code)) AND is_active FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid or inactive coupon'; END IF; IF c.valid_from IS NOT NULL AND now()<c.valid_from THEN RAISE EXCEPTION 'Coupon is not active yet'; END IF; IF coalesce(c.valid_until,c.expiry_date) IS NOT NULL AND now()>coalesce(c.valid_until,c.expiry_date) THEN RAISE EXCEPTION 'Coupon has expired'; END IF; IF c.usage_limit IS NOT NULL AND c.usage_count>=c.usage_limit THEN RAISE EXCEPTION 'Coupon usage limit has been reached'; END IF; IF p_subtotal<coalesce(c.min_order_value,0) THEN RAISE EXCEPTION 'Minimum order value is %', c.min_order_value; END IF; IF cardinality(c.applicable_product_ids)>0 AND NOT (c.applicable_product_ids && coalesce(p_product_ids,'{}')) THEN RAISE EXCEPTION 'Coupon does not apply to these products'; END IF; IF cardinality(c.applicable_categories)>0 AND NOT (c.applicable_categories && coalesce(p_category_names,'{}')) THEN RAISE EXCEPTION 'Coupon does not apply to these categories'; END IF; d:=CASE WHEN c.discount_type='fixed' THEN c.discount_value ELSE round(p_subtotal*c.discount_value/100,2) END; d:=least(d,coalesce(c.maximum_discount,d),p_subtotal); RETURN jsonb_build_object('id',c.id,'code',c.code,'discount_type',c.discount_type,'discount_value',c.discount_value,'percentage',c.percentage,'maximum_discount',c.maximum_discount,'discount',d); END; $$;
GRANT EXECUTE ON FUNCTION public.validate_coupon(text,numeric,bigint[],text[]) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.create_order_with_stock(p_customer_name text,p_phone text,p_address text,p_items jsonb,p_shipping numeric DEFAULT 0,p_status text DEFAULT 'pending',p_order_mode text DEFAULT 'offline',p_order_type text DEFAULT 'pos_sale',p_delivery_charge numeric DEFAULT 0,p_discount_amount numeric DEFAULT 0,p_manual_discount_amount numeric DEFAULT 0,p_manual_discount_type text DEFAULT 'flat',p_manual_discount_value numeric DEFAULT 0,p_coupon_code text DEFAULT NULL,p_coupon_percentage numeric DEFAULT 0,p_total_gst numeric DEFAULT 0,p_gst_enabled boolean DEFAULT false,p_payment_method text DEFAULT 'cash',p_split_details jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE i jsonb; oid uuid; inv text; subtotal numeric:=0; coupon jsonb:='{}'; cd numeric:=0; total numeric; BEGIN IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'At least one order item is required'; END IF; SELECT coalesce(sum(coalesce((value->>'line_total')::numeric,0)),0) INTO subtotal FROM jsonb_array_elements(p_items); IF nullif(btrim(p_coupon_code),'') IS NOT NULL THEN SELECT public.validate_coupon(p_coupon_code,subtotal,ARRAY(SELECT nullif(value->>'product_id','')::bigint FROM jsonb_array_elements(p_items) WHERE nullif(value->>'product_id','') IS NOT NULL),ARRAY(SELECT value->>'category' FROM jsonb_array_elements(p_items))) INTO coupon; cd:=coalesce((coupon->>'discount')::numeric,0); END IF; total:=greatest(0,subtotal+coalesce(p_total_gst,0)+coalesce(p_shipping,0)+coalesce(p_delivery_charge,0)-cd-coalesce(p_manual_discount_amount,0)); inv:='PB-'||lpad(nextval('public.invoice_number_seq')::text,8,'0'); INSERT INTO public.orders(invoice_no,user_id,customer_name,phone,address,items,subtotal,shipping,delivery_charge,discount_amount,coupon_id,coupon_code,coupon_percentage,coupon_discount_amount,manual_discount_amount,manual_discount_type,manual_discount_value,total_gst,gst_amount,gst_enabled,total,status,order_mode,order_type,payment_method,payment_mode,split_details) VALUES(inv,auth.uid(),coalesce(nullif(btrim(p_customer_name),''),'Customer'),btrim(coalesce(p_phone,'')),btrim(coalesce(p_address,'')),p_items,subtotal,coalesce(p_shipping,0),coalesce(p_delivery_charge,0),cd+coalesce(p_manual_discount_amount,0),nullif((coupon->>'id'),'')::bigint,nullif(btrim(p_coupon_code),''),coalesce((coupon->>'percentage')::numeric,0),cd,coalesce(p_manual_discount_amount,0),coalesce(p_manual_discount_type,'flat'),coalesce(p_manual_discount_value,0),coalesce(p_total_gst,0),coalesce(p_total_gst,0),coalesce(p_gst_enabled,false),total,p_status,p_order_mode,p_order_type,coalesce(p_payment_method,'cash'),coalesce(p_payment_method,'cash'),coalesce(p_split_details,'{}')) RETURNING id INTO oid; FOR i IN SELECT value FROM jsonb_array_elements(p_items) LOOP INSERT INTO public.order_items(order_id,product_id,variant_id,product_name,name,category,quantity,unit,unit_type,base_quantity,base_price,unit_price,line_total,image_url,is_manual,source,discount,gst_amount,gst_rate) VALUES(oid,nullif(coalesce(i->>'product_id',i->>'id'),'')::bigint,nullif(i->>'variant_id','')::uuid,coalesce(nullif(i->>'name',''),'Product'),coalesce(nullif(i->>'name',''),'Product'),coalesce(i->>'category',''),coalesce((i->>'quantity')::numeric,0),coalesce(i->>'unit','piece'),coalesce(i->>'unit_type','unit'),coalesce((i->>'base_quantity')::numeric,1),coalesce((i->>'base_price')::numeric,0),coalesce((i->>'base_price')::numeric,0),coalesce((i->>'line_total')::numeric,0),nullif(i->>'image_url',''),coalesce((i->>'source')='manual',false),coalesce(i->>'source','catalogue'),coalesce((i->>'discount')::numeric,0),coalesce((i->>'gst_amount')::numeric,0),coalesce((i->>'gst_rate')::numeric,0)); END LOOP; IF jsonb_object_field_text(coupon,'id') IS NOT NULL THEN UPDATE public.coupons SET usage_count=usage_count+1 WHERE id=(coupon->>'id')::bigint AND (usage_limit IS NULL OR usage_count<usage_limit); END IF; RETURN jsonb_build_object('orderId',oid,'invoiceNo',inv,'createdAt',now()); END; $$;
GRANT EXECUTE ON FUNCTION public.create_order_with_stock(text,text,text,jsonb,numeric,text,text,text,numeric,numeric,numeric,text,numeric,text,numeric,numeric,boolean,text,jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.create_advance_order(p_customer_name text,p_phone text,p_address text,p_product_name text,p_category text,p_description text,p_total_amount numeric,p_deposit_amount numeric,p_expected_delivery_date date,p_remarks text,p_payment_method text,p_created_by_name text,p_products jsonb DEFAULT '[]') RETURNS public.advance_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE a public.advance_orders; nowx timestamptz:=now(); BEGIN IF btrim(coalesce(p_customer_name,''))='' OR btrim(coalesce(p_phone,''))='' OR btrim(coalesce(p_product_name,''))='' THEN RAISE EXCEPTION 'Customer, phone, and product are required'; END IF; IF p_total_amount<=0 OR p_deposit_amount<=0 OR p_deposit_amount>=p_total_amount THEN RAISE EXCEPTION 'Deposit must be greater than zero and less than total'; END IF; IF lower(p_payment_method) NOT IN ('cash','upi','card') THEN RAISE EXCEPTION 'Invalid payment method'; END IF; INSERT INTO public.advance_orders(deposit_id,customer_name,phone,address,product_name,category,description,total_amount,deposit_amount,expected_delivery_date,remarks,reference_number,products,created_by,created_by_name) VALUES('PB-ADV-'||to_char(nowx AT TIME ZONE 'Asia/Kolkata','YYYYMMDD')||'-'||lpad(nextval('public.deposit_number_seq')::text,5,'0'),btrim(p_customer_name),btrim(p_phone),coalesce(btrim(p_address),''),btrim(p_product_name),coalesce(btrim(p_category),''),coalesce(btrim(p_description),''),round(p_total_amount,2),round(p_deposit_amount,2),p_expected_delivery_date,coalesce(btrim(p_remarks),''),'',CASE WHEN jsonb_typeof(p_products)='array' THEN p_products ELSE '[]' END,auth.uid(),coalesce(btrim(p_created_by_name),'')) RETURNING * INTO a; INSERT INTO public.advance_order_payments(advance_order_id,payment_type,amount,payment_method,remarks,received_by) VALUES(a.id,'deposit',a.deposit_amount,lower(p_payment_method),coalesce(p_remarks,''),auth.uid()); INSERT INTO public.advance_order_timeline(advance_order_id,event_type,label,remarks,created_by) VALUES(a.id,'created','Advance Order Created',coalesce(p_remarks,''),auth.uid()),(a.id,'deposit_received','Deposit Received','',auth.uid()); RETURN a; END; $$;
GRANT EXECUTE ON FUNCTION public.create_advance_order(text,text,text,text,text,text,numeric,numeric,date,text,text,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_advance_order_status(p_order_id uuid,p_status text,p_remarks text DEFAULT '') RETURNS public.advance_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.advance_orders; BEGIN IF p_status NOT IN ('pending_deposit','ready_for_delivery','waiting_final_payment','cancelled') THEN RAISE EXCEPTION 'Invalid status'; END IF; SELECT * INTO a FROM public.advance_orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND OR a.status='completed' THEN RAISE EXCEPTION 'Advance order cannot be changed'; END IF; UPDATE public.advance_orders SET status=p_status,remarks=CASE WHEN btrim(coalesce(p_remarks,''))='' THEN remarks ELSE p_remarks END WHERE id=p_order_id RETURNING * INTO a; INSERT INTO public.advance_order_timeline(advance_order_id,event_type,label,remarks,created_by) VALUES(p_order_id,p_status,replace(initcap(replace(p_status,'_',' ')),'Pending Deposit','Pending Deposit'),coalesce(p_remarks,''),auth.uid()); RETURN a; END; $$;
GRANT EXECUTE ON FUNCTION public.update_advance_order_status(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_advance_order(p_order_id uuid,p_customer_name text,p_phone text,p_address text,p_product_name text,p_category text,p_description text,p_total_amount numeric,p_expected_delivery_date date,p_remarks text,p_reference_number text,p_products jsonb DEFAULT '[]') RETURNS public.advance_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.advance_orders; BEGIN SELECT * INTO a FROM public.advance_orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND OR a.status IN ('completed','cancelled') THEN RAISE EXCEPTION 'Advance order cannot be edited'; END IF; IF p_total_amount<=a.deposit_amount THEN RAISE EXCEPTION 'Total must be greater than the deposit already received'; END IF; UPDATE public.advance_orders SET customer_name=btrim(p_customer_name),phone=btrim(p_phone),address=coalesce(btrim(p_address),''),product_name=btrim(p_product_name),category=coalesce(btrim(p_category),''),description=coalesce(btrim(p_description),''),total_amount=round(p_total_amount,2),expected_delivery_date=p_expected_delivery_date,remarks=coalesce(btrim(p_remarks),''),reference_number=coalesce(btrim(p_reference_number),''),products=CASE WHEN jsonb_typeof(p_products)='array' THEN p_products ELSE products END WHERE id=p_order_id RETURNING * INTO a; INSERT INTO public.advance_order_timeline(advance_order_id,event_type,label,created_by) VALUES(p_order_id,'edited','Advance Order Edited',auth.uid()); RETURN a; END; $$;
GRANT EXECUTE ON FUNCTION public.update_advance_order(uuid,text,text,text,text,text,text,numeric,date,text,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.add_advance_order_event(p_order_id uuid,p_event_type text,p_label text,p_remarks text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.advance_orders WHERE id=p_order_id) THEN RAISE EXCEPTION 'Advance order not found'; END IF; INSERT INTO public.advance_order_timeline(advance_order_id,event_type,label,remarks,created_by) VALUES(p_order_id,p_event_type,p_label,coalesce(p_remarks,''),auth.uid()); END; $$;
GRANT EXECUTE ON FUNCTION public.add_advance_order_event(uuid,text,text,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.complete_advance_order_v2(p_order_id uuid,p_payment_method text,p_final_amount numeric,p_coupon_code text DEFAULT NULL,p_coupon_percentage numeric DEFAULT 0,p_manual_discount numeric DEFAULT 0,p_remarks text DEFAULT '') RETURNS TABLE(order_id uuid,invoice_no text,completed_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.advance_orders; oid uuid:=gen_random_uuid(); inv text:='PB-'||lpad(nextval('public.invoice_number_seq')::text,8,'0'); nowx timestamptz:=now(); items jsonb; coupon jsonb:='{}'; cd numeric:=0; expected numeric; i jsonb; BEGIN IF lower(p_payment_method) NOT IN ('cash','upi','card') THEN RAISE EXCEPTION 'Invalid payment method'; END IF; SELECT * INTO a FROM public.advance_orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND OR a.status IN ('cancelled','completed') OR a.completed_order_id IS NOT NULL THEN RAISE EXCEPTION 'Advance order cannot be completed'; END IF; items:=CASE WHEN jsonb_typeof(a.products)='array' AND jsonb_array_length(a.products)>0 THEN a.products ELSE jsonb_build_array(jsonb_build_object('name',a.product_name,'category',a.category,'quantity',1,'base_price',a.total_amount,'line_total',a.total_amount,'unit','piece','unit_type','unit','source','advance_order')) END; IF nullif(btrim(p_coupon_code),'') IS NOT NULL THEN SELECT public.validate_coupon(p_coupon_code,a.remaining_balance,ARRAY(SELECT nullif(value->>'product_id','')::bigint FROM jsonb_array_elements(items) WHERE nullif(value->>'product_id','') IS NOT NULL),ARRAY(SELECT value->>'category' FROM jsonb_array_elements(items))) INTO coupon; cd:=coalesce((coupon->>'discount')::numeric,0); END IF; expected:=greatest(0,a.remaining_balance-cd-greatest(0,coalesce(p_manual_discount,0))); IF round(coalesce(p_final_amount,0),2)<>round(expected,2) THEN RAISE EXCEPTION 'Final amount does not match the stored balance and discounts'; END IF; INSERT INTO public.orders(id,invoice_no,user_id,customer_name,phone,address,items,subtotal,total,discount_amount,coupon_id,coupon_code,coupon_percentage,coupon_discount_amount,manual_discount_amount,order_mode,order_type,status,payment_method,payment_mode) VALUES(oid,inv,auth.uid(),a.customer_name,a.phone,a.address,items,a.total_amount,round(a.total_amount-(a.deposit_amount+expected),2),cd+coalesce(p_manual_discount,0),nullif((coupon->>'id'),'')::bigint,nullif(btrim(p_coupon_code),''),coalesce((coupon->>'percentage')::numeric,0),cd,coalesce(p_manual_discount,0),'offline','advance_order','completed',lower(p_payment_method),lower(p_payment_method)); FOR i IN SELECT value FROM jsonb_array_elements(items) LOOP INSERT INTO public.order_items(order_id,product_name,name,category,quantity,unit,unit_type,base_price,unit_price,line_total,source) VALUES(oid,coalesce(nullif(i->>'name',''),'Product'),coalesce(nullif(i->>'name',''),'Product'),coalesce(i->>'category',''),coalesce((i->>'quantity')::numeric,1),coalesce(i->>'unit','piece'),coalesce(i->>'unit_type','unit'),coalesce((i->>'base_price')::numeric,0),coalesce((i->>'base_price')::numeric,0),coalesce((i->>'line_total')::numeric,0),'advance_order'); END LOOP; INSERT INTO public.advance_order_payments(advance_order_id,payment_type,amount,payment_method,remarks,received_by) VALUES(a.id,'remaining',expected,lower(p_payment_method),coalesce(p_remarks,''),auth.uid()); UPDATE public.advance_orders SET status='completed',completed_at=nowx,completed_order_id=oid,invoice_number=inv,final_payment_method=lower(p_payment_method),remarks=CASE WHEN btrim(coalesce(p_remarks,''))='' THEN remarks ELSE p_remarks END WHERE id=a.id; INSERT INTO public.advance_order_timeline(advance_order_id,event_type,label,remarks,created_by) VALUES(a.id,'remaining_payment_received','Remaining Payment Received',coalesce(p_remarks,''),auth.uid()),(a.id,'invoice_generated','Final Invoice Generated',inv,auth.uid()); IF coupon ? 'id' THEN UPDATE public.coupons SET usage_count=usage_count+1 WHERE id=(coupon->>'id')::bigint AND (usage_limit IS NULL OR usage_count<usage_limit); END IF; RETURN QUERY SELECT oid,inv,nowx; END; $$;
GRANT EXECUTE ON FUNCTION public.complete_advance_order_v2(uuid,text,numeric,text,numeric,numeric,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_public_invoice_by_number(p_invoice_no text) RETURNS SETOF public.orders LANGUAGE sql SECURITY DEFINER STABLE SET search_path=public AS $$ SELECT * FROM public.orders WHERE invoice_no=btrim(p_invoice_no) LIMIT 1 $$;
GRANT EXECUTE ON FUNCTION public.get_public_invoice_by_number(text) TO anon,authenticated;

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY; ALTER TABLE public.product_prices ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lens_types ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lens_addons ENABLE ROW LEVEL SECURITY; ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY; ALTER TABLE public.advance_orders ENABLE ROW LEVEL SECURITY; ALTER TABLE public.advance_order_timeline ENABLE ROW LEVEL SECURITY; ALTER TABLE public.advance_order_payments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_self ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_admin()); CREATE POLICY profiles_admin_update ON public.profiles FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY catalog_read ON public.categories FOR SELECT TO anon,authenticated USING(is_active); CREATE POLICY catalog_admin ON public.categories FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY product_read ON public.products FOR SELECT TO anon,authenticated USING(is_active); CREATE POLICY product_admin ON public.products FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY variant_read ON public.product_variants FOR SELECT TO anon,authenticated USING(is_active); CREATE POLICY variant_admin ON public.product_variants FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY pricing_admin ON public.product_prices FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY lens_read ON public.lens_types FOR SELECT TO anon,authenticated USING(is_active); CREATE POLICY lens_admin ON public.lens_types FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY addon_read ON public.lens_addons FOR SELECT TO anon,authenticated USING(is_active); CREATE POLICY addon_admin ON public.lens_addons FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY coupon_active_read ON public.coupons FOR SELECT TO anon,authenticated USING(is_active AND (valid_from IS NULL OR valid_from<=now()) AND (valid_until IS NULL OR valid_until>=now())); CREATE POLICY coupon_admin ON public.coupons FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY order_admin_read ON public.orders FOR SELECT TO authenticated USING(public.is_admin() OR user_id=auth.uid()); CREATE POLICY order_admin_update ON public.orders FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY order_items_admin_read ON public.order_items FOR SELECT TO authenticated USING(public.is_admin() OR EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND o.user_id=auth.uid()));
CREATE POLICY advance_admin ON public.advance_orders FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY timeline_admin ON public.advance_order_timeline FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY payments_admin ON public.advance_order_payments FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY settings_admin ON public.store_settings FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE INDEX advance_orders_created_idx ON public.advance_orders(created_at DESC); CREATE INDEX advance_orders_status_idx ON public.advance_orders(status); CREATE INDEX order_items_order_idx ON public.order_items(order_id); CREATE INDEX orders_created_idx ON public.orders(created_at DESC);
NOTIFY pgrst, 'reload schema';
